function run_ramp_feasibility
root=fileparts(mfilename('fullpath'));cd(root);diary('ramp_feasibility_diary.log');folder=fullfile(root,'ramp3deg_feasibility');if ~exist(folder,'dir'),mkdir(folder);end
Simulink.fileGenControl('set','CacheFolder',fullfile(root,'cache'),'CodeGenFolder',fullfile(root,'codegen'),'createDir',true);
m='native_ramp3deg_feasibility';report=struct('completed',false,'case_id','M12','scope','NATIVE_3D_INFINITE_SLOPE_FEASIBILITY_NOT_THRESHOLD','slope_deg',3,'step_s',25e-6,'sensor_log_s',.001,'error','');timer=tic;
try
 file=fullfile(folder,[m '.slx']);build_native(file,0,25e-6,3,.001);bs=find_system(m,'LookUnderMasks','all','Type','Block');plane=find_named(bs,'Infinite Plane');world=find_named(bs,'World Frame');
 rt=add_block(find_named(bs,'RT_LIFT'),[m '/SLOPE_FRAME']);set_param(rt,'TranslationMethod','None','RotationMethod','StandardAxis','RotationStandardAxis','+Y','RotationAngle','-3','RotationAngleUnits','deg');
 simscape.removeConnection(plane,'R');simscape.addConnection(world,'W',rt,'B');simscape.addConnection(rt,'F',plane,'R');
 jf=find_named(bs,'J_FREE');set_param(jf,'SphPositionTargetRotationMethod','StandardAxis','SphPositionTargetRotationStandardAxis','+Y','SphPositionTargetRotationAngle','-3','SphPositionTargetRotationAngleUnits','deg','PxPositionTargetValue',num2str(.075*sind(3),17));
 sensor=[m '/AXLE_MIDPOINT_SENSOR'];set_param(sensor,'SenseZ','on');cv=add_block(find_named(bs,'CONV_ROBOT_X'),[m '/AXLE_CONV_Z']);set_param(cv,'Unit','m');simscape.addConnection(sensor,'z_out',cv,'input');add_export(cv,'axle_z_m',.001);
 cmd=table([0;.3;2.4;3],[0;.4;0;0],[0;.4;0;0],'VariableNames',{'time_s','tau_left_Nm','tau_right_Nm'});mw=get_param(m,'ModelWorkspace');assignin(mw,'axle_command_matrix',table2array(cmd));
 add_block('simulink/Sources/From Workspace',[m '/AXLE_ZOH_TRACE'],'VariableName','axle_command_matrix','Interpolate','off','OutputAfterFinalValue','Holding final value','SampleTime','0');dm=add_block('simulink/Signal Routing/Demux',[m '/AXLE_COMMAND_SPLIT'],'Outputs','2');add_line(m,'AXLE_ZOH_TRACE/1','AXLE_COMMAND_SPLIT/1');wire_axle_inputs(m,dm,[1 2]);save_system(m,file);writetable(cmd,fullfile(folder,'commands.csv'));report.model_sha256=file_sha256(file);report.command_sha256=file_sha256(fullfile(folder,'commands.csv'));
 status_event('Running native 3-degree infinite-plane slope feasibility (finite threshold not modeled).');in=Simulink.SimulationInput(m);in=in.setModelParameter('ReturnWorkspaceOutputs','on','SaveTime','off','Timeout',600);out=sim(in);report.error=out.ErrorMessage;save(fullfile(folder,'result.mat'),'out','report','-v7.3');T=export_native(out,folder,.001);report.end_s=T.time_s(end);report.completed=abs(report.end_s-3)<1e-9&&isempty(report.error);report.initial_x_m=T.axle_x_m_1(1);report.final_x_m=T.axle_x_m_1(end);report.initial_z_m=T.axle_z_m_1(1);report.final_z_m=T.axle_z_m_1(end);report.final_pitch_deg=T.axle_angles_deg_2(end);report.max_penetration_m=max([T.pen_L_1 T.pen_R_1 T.pen_C_1],[],1);
 f=figure('Visible','off','Color','w','Position',[0 0 1000 700]);tiledlayout(2,2);nexttile;plot(T.axle_x_m_1,T.axle_z_m_1);xlabel('World x (m)');ylabel('Axle z (m)');grid on;nexttile;plot(T.time_s,T.axle_angles_deg_2);ylabel('Pitch (deg)');grid on;nexttile;plot(T.time_s,[T.normal_L_3 T.normal_R_3 T.normal_C_3]);ylabel('Contact normal (N)');grid on;nexttile;plot(T.time_s,[T.pen_L_1 T.pen_R_1 T.pen_C_1]*1000);ylabel('Penetration (mm)');grid on;sgtitle('Native 3D infinite slope feasibility, +3 degree uphill');exportgraphics(f,fullfile(folder,'ramp_feasibility.png'));close(f);
catch err,report.error=getReport(err,'extended','hyperlinks','off');disp(report.error);end
report.wall_s=toc(timer);report.threshold_status='NOT_IMPLEMENTED: Infinite Plane has no edge or height discontinuity. A finite threshold requires explicit solid/grid-surface geometry and additional wheel/obstacle contact pairs, plus corner/contact convergence validation. No traversal claim.';write_json(fullfile(folder,'report.json'),report);status_event(sprintf('Ramp feasibility completed=%d; finite threshold explicitly not implemented.',report.completed));if bdIsLoaded(m),close_system(m,0);end;diary off
end
